#!/bin/bash
# Build (incrementally), flash and monitor the I2S microphone demo app.
#
# Unlike run-esp.sh, the dataset file is deliberately NOT flashed: the demo
# app never reads the dataset partition, and uploading the 8 MB dataset over
# serial is very slow. The model is still copied and embedded in the firmware,
# so it is flashed. An existing dataset.bin (a disposable copy from a previous
# run, regenerated by run-esp.sh) is simply removed before building so the
# CMake build system does not register it as a flash target.
set -euo pipefail

VERBOSE=true  # the demo streams stats forever, so show build/flash and serial output in real time

# Manual arg parsing: supports -q and one positional model path
POSITIONALS=()
while [ $# -gt 0 ]; do
  case "$1" in
  -q) VERBOSE=false ; shift ;;
  -h|--help)
    echo "Usage: $0 [-q] <path-to-model.espdl>" >&2
    echo "  -q  quiet build/flash output (serial output is always streamed live)" >&2
    exit 0
    ;;
  -*)
    echo "Unknown option: $1" >&2
    echo "Usage: $0 [-q] <path-to-model.espdl>" >&2
    exit 1
    ;;
  *) POSITIONALS+=("$1") ; shift ;;
  esac
done

if [ ${#POSITIONALS[@]} -ne 1 ]; then
  echo "Usage: $0 [-q] <path-to-model.espdl>" >&2
  exit 1
fi
MODEL_PATH="${POSITIONALS[0]}"

if [ ! -f "$MODEL_PATH" ]; then
  echo "Error: model file not found: $MODEL_PATH" >&2
  exit 1
fi

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
if [ ! -d "$SCRIPT_DIR/esp-dl/main/apps/demo" ]; then
  echo "Error: demo app not found (esp-dl/main/apps/demo)" >&2
  exit 1
fi

set +eu
source ~/.espressif/tools/activate_idf_v6.0.1.sh >/dev/null
set -eu

IDF_PY="$IDF_PATH/tools/idf.py"
PYTHON="$IDF_PYTHON_ENV_PATH/bin/python"

cp "$MODEL_PATH" "$SCRIPT_DIR/esp-dl/main/model/model.espdl"
echo "demo: using model $(basename "$MODEL_PATH")"

# Remove a leftover dataset.bin (from a previous run-esp.sh) so it is not
# registered as a flash target: the demo never reads the dataset partition,
# and flashing 8 MB over serial is slow. run-esp.sh regenerates this file.
rm -f "$SCRIPT_DIR/esp-dl/main/model/dataset.bin"

cd "$SCRIPT_DIR/esp-dl"

# Build only if necessary: idf.py uses ninja, so an unchanged build is a no-op.
# Passing ACTIVE_APP=demo reconfigures CMake if a different app was built before.
APP_CMAKE_ARGS=(-D "ACTIVE_APP=demo")

if $VERBOSE; then
  "$PYTHON" "$IDF_PY" "${APP_CMAKE_ARGS[@]}" build 2>&1 || exit 1
  "$PYTHON" "$IDF_PY" "${APP_CMAKE_ARGS[@]}" -p /dev/ttyACM0 flash 2>&1 || exit 1
else
  # Capture build output; only print on failure
  BUILD_OUT=$("$PYTHON" "$IDF_PY" "${APP_CMAKE_ARGS[@]}" build 2>&1) || {
    echo "$BUILD_OUT" | awk 'length < 300'
    exit 1
  }

  FLASH_OUT=$("$PYTHON" "$IDF_PY" "${APP_CMAKE_ARGS[@]}" -p /dev/ttyACM0 flash 2>&1) || {
    echo "$FLASH_OUT" | awk 'length < 300'
    exit 1
  }
fi

echo "demo: flashed, monitoring serial output (Ctrl+C to stop)" >&2

# Monitor serial output — the demo streams forever, so print lines in real
# time until interrupted. A mic init failure or a crash ends the session with
# a non-zero exit code.
"$PYTHON" - /dev/ttyACM0 <<'PYEOF'
import serial, sys

PORT            = sys.argv[1]
BAUD            = 115200
FAIL_SENTINELS  = ["MIC_TEST_FAIL", "INFERENCE_OOM", "INFERENCE_FAIL"]
CRASH_MARKERS   = ["Guru Meditation Error", "abort() was called", "Backtrace:", "rst:0x"]

with serial.Serial(PORT, BAUD, timeout=0.1) as ser:
    try:
        while True:
            raw = ser.readline()
            if not raw:
                continue
            line = raw.decode("utf-8", errors="replace").rstrip()
            sys.stdout.write(line + "\n")
            sys.stdout.flush()
            if any(s in line for s in FAIL_SENTINELS):
                print("\ndemo: device reported a failure: " + line, file=sys.stderr)
                sys.exit(1)
            if any(m in line for m in CRASH_MARKERS):
                for _ in range(20):
                    extra = ser.readline()
                    if extra:
                        print(extra.decode("utf-8", errors="replace").rstrip())
                print("\ndemo: device crashed", file=sys.stderr)
                sys.exit(2)
    except KeyboardInterrupt:
        print("\ndemo: monitoring stopped", file=sys.stderr)
        sys.exit(0)
PYEOF